(()=>{const mount=document.querySelector('.hero-image');if(!mount||!window.THREE||!THREE.GLTFLoader)return;
const T=THREE,scene=new T.Scene();scene.background=new T.Color(0x10191c);const camera=new T.PerspectiveCamera(36,1,.1,200);const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;renderer.shadowMap.enabled=true;renderer.domElement.className='car-canvas';mount.prepend(renderer.domElement);scene.add(new T.HemisphereLight(0xcce9ff,0x26302e,2.2));for(const [x,y,z,c,p]of [[-5,8,4,0xffffff,3],[5,7,-4,0x91d8e8,2]]){const light=new T.DirectionalLight(c,p);light.position.set(x,y,z);scene.add(light)}
let model,paint=[],dirty=0;const status=document.createElement('span');status.className='model-status';status.textContent='3D машин ачаалж байна…';mount.append(status);
new T.GLTFLoader().load('urus_absoluttm.glb',g=>{model=g.scene;const bounds=new T.Box3().setFromObject(model),size=bounds.getSize(new T.Vector3()),center=bounds.getCenter(new T.Vector3());model.position.sub(center);const scale=5.5/Math.max(size.x,size.z);model.scale.setScalar(scale);model.position.y+=size.y*scale/2+.15;model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;if(o.material){o.material=o.material.clone();paint.push(o.material)}}});scene.add(model);camera.position.set(6,3.2,8);camera.lookAt(0,1,0);status.remove();apply(0)},undefined,()=>{status.textContent='3D загвар ачаалж чадсангүй'});
const ground=new T.Mesh(new T.PlaneGeometry(200,200),new T.MeshStandardMaterial({color:0x1b292c,roughness:.42,metalness:.18}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);
const resize=()=>{const w=mount.clientWidth,h=mount.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(mount);resize();
function apply(p){dirty=1-p;paint.forEach(m=>{if(!m.userData.baseColor&&m.color)m.userData.baseColor=m.color.clone();if(m.color)m.color.copy(m.userData.baseColor).lerp(new T.Color(0x775a3a),dirty*.55);if(m.roughness!==undefined){if(m.userData.baseRoughness===undefined)m.userData.baseRoughness=m.roughness;m.roughness=Math.min(1,m.userData.baseRoughness+dirty*.35)}})}const slider=mount.querySelector('.wash-control input');slider?.addEventListener('input',()=>apply(Number(slider.value)/100));
let dragging=false,last=0;renderer.domElement.addEventListener('pointerdown',e=>{dragging=true;last=e.clientX;renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointermove',e=>{if(dragging&&model){model.rotation.y+=(e.clientX-last)*.009;last=e.clientX}});renderer.domElement.addEventListener('pointerup',()=>dragging=false);const animate=()=>{requestAnimationFrame(animate);if(model&&!dragging)model.rotation.y+=.001;renderer.render(scene,camera)};animate();})();
